-- Esquema inicial de ImpactoLocal para PostgreSQL/Neon.
-- Solo crea objetos que aún no existen; conserva las tablas y los datos actuales.

CREATE TABLE IF NOT EXISTS "CLIENTES" (
  "ID" BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "NOMBRE DE USUARIO" VARCHAR(120) NOT NULL,
  "CORREO ELECTRÓNICO" VARCHAR(254) NOT NULL,
  "CONTRASEÑA" TEXT NOT NULL,
  "NÚMERO TELEFÓNICO" VARCHAR(9),
  "DNI" VARCHAR(8),
  "OCUPACIÓN" VARCHAR(120)
);

CREATE UNIQUE INDEX IF NOT EXISTS clientes_email_lower_idx
  ON "CLIENTES" (lower("CORREO ELECTRÓNICO"));

-- Tabla legada consultada como alternativa por el inicio de sesión.
CREATE TABLE IF NOT EXISTS "PERSONAS" (
  "ID" BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "NOMBRE DE USUARIO" VARCHAR(120) NOT NULL,
  "CORREO ELECTRÓNICO" VARCHAR(254),
  "CONTRASEÑA" TEXT NOT NULL
);

CREATE TABLE IF NOT EXISTS "ORGANIZACIONES" (
  "ID" BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "NOMBRE DE USUARIO" VARCHAR(120) NOT NULL,
  "CORREO ELECTRÓNICO" VARCHAR(254) NOT NULL,
  "CONTRASEÑA" TEXT NOT NULL,
  "OCUPACIÓN" VARCHAR(120),
  "WEB" TEXT,
  "INSTAGRAM" TEXT,
  "FACEBOOK" TEXT,
  "TIK TOK" TEXT,
  "TIPO" VARCHAR(20)
);

ALTER TABLE "ORGANIZACIONES" ADD COLUMN IF NOT EXISTS "TIPO" VARCHAR(20);

CREATE UNIQUE INDEX IF NOT EXISTS organizaciones_usuario_lower_idx
  ON "ORGANIZACIONES" (lower("NOMBRE DE USUARIO"));
CREATE UNIQUE INDEX IF NOT EXISTS organizaciones_email_lower_idx
  ON "ORGANIZACIONES" (lower("CORREO ELECTRÓNICO"));

CREATE TABLE IF NOT EXISTS "ADMINS" (
  "ID" BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "NOMBRE DE USUARIO" VARCHAR(120) NOT NULL,
  "CORREO ELECTRÓNICO" VARCHAR(254) NOT NULL,
  "CONTRASEÑA" TEXT NOT NULL
);

CREATE UNIQUE INDEX IF NOT EXISTS admins_email_lower_idx
  ON "ADMINS" (lower("CORREO ELECTRÓNICO"));

CREATE TABLE IF NOT EXISTS solicitudes_registro_org (
  id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  tipo VARCHAR(20) NOT NULL CHECK (tipo IN ('ONG', 'VOLUNTARIADO')),
  usuario VARCHAR(120) NOT NULL,
  email VARCHAR(254) NOT NULL,
  password_hash TEXT NOT NULL,
  ocupacion VARCHAR(120) NOT NULL,
  web TEXT,
  instagram TEXT,
  facebook TEXT,
  tiktok TEXT,
  estado VARCHAR(20) NOT NULL DEFAULT 'pendiente'
    CHECK (estado IN ('pendiente', 'aprobada', 'rechazada')),
  motivo_rechazo TEXT,
  creado_en TIMESTAMPTZ NOT NULL DEFAULT now()
);

CREATE INDEX IF NOT EXISTS solicitudes_registro_org_estado_fecha_idx
  ON solicitudes_registro_org (estado, creado_en DESC);
